def save(lst):
    tmp = OUT + ".tmp"
    with open(tmp, "w") as f:
        json.dump(lst, f, indent=4, ensure_ascii=False)
    os.replace(tmp, OUT)

for idx in range(23, 30):
    r = src[idx]
    name = r["Name"]
    rec = {
        "Name": r["Name"],
        "Title": r["Title"],
        "Short Hypothesis": SH[name],
        "Related Work": r["Related Work"] + RW[name],
        "Abstract": ABS[name],
        "Experiments": r["Experiments"] + EXP[name],
        "Risk Factors and Limitations": r["Risk Factors and Limitations"],
    }
    assert list(rec.keys()) == FIELDS
    out.append(rec)
    save(out)
    print("appended idx", idx, name, "-> out len", len(out))

print("DONE. final len", len(out))
